#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path

PAYLOADS = {
    'scripts/freeze_japan_academy_imperial_manual_image_queue_v1.py': {"sha256": 'df2d53e3e6f7dae01e1987d82e4a54743c6f8a74c397a7340c1267863aa03f2f', "payload": ''},
    'scripts/collect_japan_academy_imperial_manual_images_v1.py': {"sha256": '71677b7b93d9a3ca195b161e55a6d7c4818106e05c0201840d141310533f669d', "payload": ''},
}

def main() -> int:
    for target_raw, meta in PAYLOADS.items():
        target = Path(target_raw)
        data = gzip.decompress(base64.b64decode(meta["payload"]))
        got = hashlib.sha256(data).hexdigest()
        if got != meta["sha256"]:
            raise RuntimeError(f"Embedded payload SHA mismatch for {target}: {got}")
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists() and hashlib.sha256(target.read_bytes()).hexdigest() == got:
            print(f"ALREADY INSTALLED: {target} sha256={got}")
            continue
        if target.exists():
            backup = target.with_suffix(target.suffix + ".pre_manual_image_v1.bak")
            if not backup.exists():
                backup.write_bytes(target.read_bytes())
            print(f"backup={backup}")
        target.write_bytes(data)
        print(f"INSTALL OK: {target} sha256={got}")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
